
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_lc94_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_lc94", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.459686789471208e+01, 9.093104763254827e+01, 8.591775908439580e+01, 7.921105070211519e+01, 7.051714834333089e+01, 5.974203783430067e+01, 4.721072212707670e+01, 3.388363833557111e+01, 2.136511038749781e+01, 1.142827537141789e+01, 5.110833249905342e+00, 2.545606512184533e+00, 1.916555855064946e+00, 1.275291579642785e+00, 6.457946235950254e-01, 2.478517324205707e-01, 7.442039874425374e-02, 1.634219600451263e-02, 4.341242160018063e-04, 7.821100406312493e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


